/**
 * 섹션 1 · 유닛 3 — 한국어를 공부해요
 * 출처: 서울대 한국어 1A 3과
 *
 * 배우는 것
 *   동사        자다·공부하다·일하다·운동하다·숙제를 하다·옷을 사다
 *               영화를 보다·친구를 만나다·태권도를 배우다·밥을 먹다
 *               커피를 마시다·책을 읽다
 *   장소        도서관·집·백화점·시장·공원·커피숍·극장·학교·식당·회사
 *   문법        V-아요/어요   ·   N을/를   ·   N에서   ·   안 V
 *
 * 유닛 3 규칙 (유닛 2와 같다)
 *   - 타이핑 계열은 여전히 안 넣는다. 유닛 5부터.
 *   - 빈칸은 전부 단일 빈칸. 다중 빈칸은 섹션 2부터.
 *   - word_matching / audio_match 는 짧은 단어만, 항상 5쌍.
 *   - speaking 은 한 사람이 말하는 짧은 문장만, 16자 이내.
 *   - 같은 타입을 연달아 두지 않는다.
 *   - reply_builder 는 대화를 다루는 레슨에만 하나씩.
 *
 * 이 유닛의 함정 — 오답 보기로 매번 판단하게 만드는 것
 *   1. 받침 → 을/를    밥을(O) 밥를(X) · 커피를(O) 커피을(X)
 *   2. 모음 → 아요/어요  자요(O) 자어요(X) · 먹어요(O) 먹아요(X)
 *   3. 하다 → 해요      공부해요(O) 공부하아요(X)
 *   4. 안 의 자리       공부 안 해요(O) 안 공부해요(X) · 안 먹어요(O) 먹 안 어요(X)
 */

